/* Static public use-case assessment page. Navigation is rendered by the
   shared canonical sidebar script; no private API or model interaction. */
(()=>{"use strict";const menu=document.getElementById("menu-toggle"),side=document.getElementById("site-navigation");if(!menu||!side)return;menu.addEventListener("click",()=>{const open=!side.classList.contains("is-open");side.classList.toggle("is-open",open);menu.setAttribute("aria-expanded",String(open));});side.addEventListener("click",e=>{if(e.target instanceof Element&&e.target.closest("a[href]")){side.classList.remove("is-open");menu.setAttribute("aria-expanded","false");}});document.addEventListener("keydown",e=>{if(e.key==="Escape"&&side.classList.contains("is-open")){side.classList.remove("is-open");menu.setAttribute("aria-expanded","false");menu.focus();}});})();